<script setup>
import { reactive, watch, computed } from 'vue';
import ModalDialog from './ModalDialog.vue';
import { loadGoogle } from '../services/google-auth.js';
const props = defineProps({ open: Boolean, youtube: Object });
const emit = defineEmits(['close']);
const form = reactive({ mode: 'public', channel: '', clientId: '', days: 28, apiKey: '', remember: false, agree: false });
const y = props.youtube;
const origin = location.origin;
watch(() => props.open, open => { if (open) Object.assign(form, y.config.value, { apiKey: y.apiKey.value, remember: y.remember.value, agree: false }); });
watch(() => [props.open, form.mode], ([open, mode]) => { if (open && mode === 'owner') loadGoogle().catch(() => { /* Connect shows the actionable loading error. */ }); });
const disabled = computed(() => y.busy.value || y.authBusy.value);
const dirty = computed(() => form.mode !== y.config.value.mode || form.channel.trim() !== y.config.value.channel || form.clientId.trim() !== y.config.value.clientId || Number(form.days) !== y.config.value.days || (form.mode === 'public' && form.apiKey.trim() !== y.apiKey.value));
async function forget() { await y.forget(); form.apiKey = ''; form.remember = false; }
async function disconnect() { await y.disconnect(); form.apiKey = ''; form.remember = false; }
</script>
<template><ModalDialog :open="open" title="YouTube setup" @close="emit('close')"><div class="yt-panel"><h2>Connect your YouTube channel</h2><p>Load public video dates and totals with your API key, or sign in to see your scheduled uploads and private analytics.</p>
  <fieldset :disabled="disabled" class="connection-fields"><label for="yt-mode">Connection type</label><select id="yt-mode" v-model="form.mode" class="yt-input"><option value="public">Public videos - API key</option><option value="owner">My channel + analytics - Google sign-in</option></select><label for="yt-channel">Channel ID or @handle</label><input id="yt-channel" v-model="form.channel" class="yt-input" placeholder="UC... or @yourchannel" maxlength="150" autocomplete="off">
  <template v-if="form.mode === 'public'"><label for="yt-api-key">YouTube Data API key</label><input id="yt-api-key" v-model="form.apiKey" class="yt-input" type="password" maxlength="200" autocomplete="off" spellcheck="false" placeholder="Enter your API key"><label class="selection-check"><input v-model="form.remember" type="checkbox">Remember this API key on this device</label><p class="yt-fetched">Session only by default. Remembering saves it in this browser's IndexedDB. Restrict the key to YouTube Data API v3 and your website in Google Cloud. Browser storage is not encrypted by this app. Keys are never in board exports.</p></template>
  <template v-else><label for="yt-client">Your Google OAuth web client ID</label><input id="yt-client" v-model="form.clientId" class="yt-input" placeholder="...apps.googleusercontent.com" maxlength="300" autocomplete="off"><p class="yt-fetched">Enable YouTube Data API v3 and YouTube Analytics API in your own project. Register this JavaScript origin: <code>{{ origin }}</code>. Never enter a client secret.</p><label for="yt-range">Analytics period</label><select id="yt-range" v-model.number="form.days" class="yt-input"><option :value="7">Last 7 calendar days</option><option :value="28">Last 28 calendar days</option><option :value="90">Last 90 calendar days</option></select></template>
  <label class="selection-check"><input v-model="form.agree" type="checkbox">I agree to the <RouterLink to="/privacy" target="_blank">data-use notice</RouterLink> and <a href="https://www.youtube.com/t/terms" target="_blank" rel="noopener noreferrer">YouTube terms</a>.</label></fieldset>
  <p role="status">{{ y.connected.value ? 'Connected: ' + (y.cache.value?.channelTitle || 'Google session') : y.cache.value ? 'Saved data: ' + y.cache.value.channelTitle : 'Not connected' }}</p>
  <div class="yt-controls"><button class="btn btn-primary" :disabled="disabled" @click="y.connect(form)">{{ y.authBusy.value ? 'Waiting for Google...' : form.mode === 'public' ? 'Load public videos' : 'Connect Google' }}</button><button class="btn btn-quiet" :disabled="disabled || !y.ready.value || dirty" @click="y.refresh()">Refresh</button><button class="btn btn-quiet" :disabled="disabled || (!y.connected.value && !y.apiKey.value)" @click="disconnect">Disconnect</button></div>
  <p role="status" :class="{ 'yt-error': y.error.value }">{{ y.message.value }}</p><p class="yt-fetched">{{ y.stamp.value }}</p>
  <details><summary>What each option includes</summary><p>API key: public uploads and public lifetime view, like and comment totals. Private schedules and private reports require Google sign-in.</p><p>Google sign-in: your upload metadata, including schedules, and private reports for linked public videos. Only read permissions are requested. Tokens stay in memory: reconnect after reload or expiry.</p><p>Private reports end yesterday in Pacific time and can lag. Missing metrics are unavailable, not zero. Refresh is manual; reload displays dated saved data.</p></details>
  <details><summary>Channel videos ({{ y.cache.value?.videos.length || 0 }})</summary><div v-for="v in y.cache.value?.videos || []" :key="v.id" class="yt-video"><a :href="v.privacyStatus === 'private' && v.publishAt ? 'https://studio.youtube.com/video/' + v.id + '/edit' : 'https://www.youtube.com/watch?v=' + v.id" target="_blank" rel="noopener noreferrer">{{ v.title }}</a><span>{{ v.privacyStatus === 'private' && v.publishAt ? 'Scheduled ' + v.publishAt : v.publishedAt }}</span></div></details>
  <div class="yt-controls"><button class="btn btn-quiet" :disabled="disabled || !y.cache.value" @click="y.clear()">Clear saved YouTube data</button><button class="btn btn-quiet" :disabled="disabled || !y.apiKey.value" @click="forget">Forget API key</button><button class="btn btn-quiet" :disabled="disabled || !y.connected.value" @click="y.revoke()">Revoke Google access</button></div><p class="yt-fetched"><a href="https://myaccount.google.com/connections" target="_blank" rel="noopener noreferrer">Manage Google app access</a> · See README for setup instructions.</p>
</div></ModalDialog></template>
